@app.get("/recherche")
def recherche(q: str):
    sql = ("SELECT nom FROM produits "
           f"WHERE nom LIKE '%{q}%'")
    lignes = db.execute(sql).fetchall()
    items = "".join(f"<li>{n}</li>" for (n,) in lignes)
    titre = f"<p>Résultats pour {q}</p>"
    return HTMLResponse(titre + items)
